-- Enrichissement des 225 références existantes depuis le CSV conservé dans supabase/reference.
-- Toutes les colonnes originales sont conservées dans source_data (y compris les champs vides).
-- Les valeurs complexes (ex. bonus de bouclier) restent du texte, sans conversion approximative.
-- La ligne de périmètre est une note documentaire, pas un objet ; elle reste dans le CSV original.
-- Aucune création d'objet de campagne. Réexécutable, conserve tous les identifiants.
begin;
alter table public.pf2e_equipment_references
  add column if not exists source_data jsonb,
  add column if not exists weapon_range_type text check (weapon_range_type in ('melee', 'ranged')),
  add column if not exists category text,
  add column if not exists damage text,
  add column if not exists range_label text,
  add column if not exists reload_label text,
  add column if not exists bulk_label text,
  add column if not exists hands_label text,
  add column if not exists weapon_group text,
  add column if not exists traits_label text,
  add column if not exists book_reference text,
  add column if not exists armor_class_bonus text,
  add column if not exists dexterity_cap text,
  add column if not exists check_penalty text,
  add column if not exists speed_penalty text,
  add column if not exists strength_requirement text,
  add column if not exists hardness_label text,
  add column if not exists hit_points_label text,
  add column if not exists broken_threshold_label text;

create temporary table equipment_source_import on commit drop as
