do $$
begin
  if (select count(*) from equipment_source_import) <> 225 then raise exception '225 objets attendus'; end if;
  if exists (
    select 1 from equipment_source_import src
    where (select count(*) from public.pf2e_equipment_references ref
      where replace(ref.aon_url, '&NoRedirect=1', '') = replace(src.row_data->>'Source', '&NoRedirect=1', '') and ref.name_en = src.row_data->>'Nom officiel (EN)') <> 1
  ) then raise exception 'Référence absente ou ambiguë : import annulé'; end if;
end $$;

update public.pf2e_equipment_references ref set
  source_data = src.row_data,
  weapon_range_type = case src.row_data->>'Type' when 'Mêlée' then 'melee' when 'Distance' then 'ranged' else null end,
  item_type = nullif(src.row_data->>'Type', ''),
  level = nullif(src.row_data->>'Niveau', '')::integer,
  rarity = nullif(src.row_data->>'Rareté', ''),
  category = nullif(src.row_data->>'Catégorie', ''),
  damage = nullif(src.row_data->>'Dégâts', ''),
  range_label = nullif(src.row_data->>'Portée', ''),
  reload_label = nullif(src.row_data->>'Rechargement', ''),
  bulk_label = nullif(src.row_data->>'Bulk', ''),
  hands_label = nullif(src.row_data->>'Mains', ''),
  weapon_group = nullif(src.row_data->>'Groupe', ''),
  traits_label = nullif(src.row_data->>'Traits', ''),
  book_reference = nullif(src.row_data->>'Livre', ''),
  armor_class_bonus = nullif(src.row_data->>'Bonus CA', ''),
  dexterity_cap = nullif(src.row_data->>'Dex max.', ''),
  check_penalty = nullif(src.row_data->>'Pénalité tests', ''),
  speed_penalty = nullif(src.row_data->>'Pénalité vitesse', ''),
  strength_requirement = nullif(src.row_data->>'Force requise', ''),
  hardness_label = nullif(src.row_data->>'Dureté', ''),
  hit_points_label = nullif(src.row_data->>'PV', ''),
  broken_threshold_label = nullif(src.row_data->>'Seuil de rupture (BT)', '')
from equipment_source_import src
where replace(ref.aon_url, '&NoRedirect=1', '') = replace(src.row_data->>'Source', '&NoRedirect=1', '') and ref.name_en = src.row_data->>'Nom officiel (EN)';
commit;
